const qzData=[{"q":"¿Quién le puso nombre a la metacognición, y en qué año?","o":["a) Flavell, en 1979","b) Nelson, en 1990","c) Koriat, en 1997","d) Narens, en 1979"],"c":0},{"q":"En el mapa de Nelson y Narens, el nivel objeto es…","o":["a) El que vigila el trabajo","b) El que apunta la brecha","c) El que lee, resuelve y memoriza","d) El que decide cuándo parar"],"c":2},{"q":"El monitoreo es la corriente que…","o":["a) Baja decisiones al trabajo","b) Sube información de cómo va el trabajo","c) Borra lo que no sirve","d) Reparte el tiempo de estudio"],"c":1},{"q":"Las tres decisiones clásicas del timón son…","o":["a) Leer, subrayar, copiar","b) Predecir, medir, apuntar","c) Sumar, restar, comparar","d) Seguir, cambiar de técnica, abandonar"],"c":3},{"q":"La falla habitual del estudio está en…","o":["a) El timón: las decisiones son absurdas","b) El cuaderno: está mal tomado","c) El vigía: los partes que suben son falsos","d) La memoria: es demasiado corta"],"c":2},{"q":"«Me suena» es una pista de…","o":["a) Dominio del tema","b) Comprensión profunda","c) Buena calibración","d) Reconocimiento, que no es recuerdo"],"c":3},{"q":"La única lectura fiable del propio saber sale de…","o":["a) Releer con más atención","b) Producir la respuesta con el material cerrado","c) Subrayar con colores","d) Escuchar la explicación otra vez"],"c":1},{"q":"La brecha del registro es la diferencia entre…","o":["a) Lo predicho y el resultado real","b) Horas invertidas y páginas leídas","c) XP ganados y XP posibles","d) Lo fácil y lo difícil"],"c":0},{"q":"La meta del registro del vigía es…","o":["a) Brecha vista: conocer el sesgo propio","b) Brecha cero desde la primera semana","c) Acumular la mayor cantidad de horas","d) Predecir siempre nota máxima"],"c":0},{"q":"¿Cuándo se califica de verdad una sesión de estudio?","o":["a) Al terminarla, por la sensación","b) Al día siguiente, con la comprobación","c) Nunca: no hace falta","d) Al final del mes, por promedio"],"c":1}];
