const identifyTaskDB=[{"s":"Sube partes de cómo va el trabajo.","type":"El monitoreo (el vigía)"},{"s":"Baja al piso de abajo las decisiones de seguir, cambiar o parar.","type":"El control (el timón)"},{"s":"El piso que lee, resuelve y memoriza.","type":"El nivel objeto"},{"s":"El piso que vigila y administra el estudio.","type":"El metanivel"},{"s":"La predicción sobre el propio saber, hecha antes de la prueba.","type":"El juicio de aprendizaje"},{"s":"La diferencia entre lo que se predijo y lo que salió.","type":"La brecha"},{"s":"Ver la página y decir «esto me suena».","type":"Reconocimiento (pista engañosa)"},{"s":"Cerrar el material y producir la respuesta.","type":"La comprobación (recuperación)"},{"s":"Decidir bien sobre datos malos.","type":"La falla habitual"},{"s":"Apuntar predicción, fecha, resultado y brecha.","type":"El registro del vigía"}];
const classifyTaskDB=[{"w":"«Ya me lo sé»","gen":"Parte del vigía","n":"Sale de la fluidez de releer","g":"Durante el estudio","t":"Monitoreo (engañoso)"},{"w":"«Cambio a tarjetas»","gen":"Decisión del timón","n":"Cambia la técnica","g":"Durante el estudio","t":"Control"},{"w":"Resolver la división","gen":"Trabajo","n":"Produce la tarea","g":"Piso de abajo","t":"Nivel objeto"},{"w":"«Voy a sacar 85»","gen":"Parte del vigía","n":"Predicción por escrito","g":"Antes de la prueba","t":"Juicio de aprendizaje"},{"w":"Reproducir a cuaderno cerrado","gen":"Comprobación","n":"Produce sin material delante","g":"Después del estudio","t":"Monitoreo (fiable)"},{"w":"«Paro por hoy»","gen":"Decisión del timón","n":"Regla de parada","g":"Durante el estudio","t":"Control"},{"w":"La brecha de la semana","gen":"Registro","n":"Predicho contra real","g":"Después de la prueba","t":"Calibración"},{"w":"«Me suena»","gen":"Parte del vigía","n":"Sale de reconocer la página","g":"Durante el estudio","t":"Monitoreo (engañoso)"},{"w":"Leer el capítulo","gen":"Trabajo","n":"Entra material nuevo","g":"Piso de abajo","t":"Nivel objeto"},{"w":"«Repaso primero lo que falló»","gen":"Decisión del timón","n":"Usa un dato comprobado","g":"Después de la comprobación","t":"Control con datos"}];
const completeTaskDB=[{"s":"El vigía sube ___ del trabajo.","opts":["partes","órdenes","notas"],"ans":"partes"},{"s":"El timón baja ___.","opts":["decisiones","partes","sensaciones"],"ans":"decisiones"},{"s":"Nelson y Narens ordenaron el mapa en dos ___.","opts":["pisos","listas","fases"],"ans":"pisos"},{"s":"La falla habitual está en el ___.","opts":["vigía","timón","cuaderno"],"ans":"vigía"},{"s":"Un parte vale por su ___.","opts":["origen","fuerza","hora"],"ans":"origen"},{"s":"La meta del registro no es brecha cero: es brecha ___.","opts":["vista","corta","nueva"],"ans":"vista"},{"s":"La sesión se califica al día siguiente, con la ___.","opts":["comprobación","sensación","relectura"],"ans":"comprobación"},{"s":"Saber no se siente: se ___.","opts":["comprueba","repite","subraya"],"ans":"comprueba"}];
const explainQuestions=[{"q":"Explica el mapa de los dos pisos de Nelson y Narens con un ejemplo de esta casa.","ans":"Abajo está el nivel objeto: el que hace el trabajo de aprender. Cuando Jael resuelve una división o lee el capítulo del sistema nervioso, trabaja el piso de abajo. Arriba está el metanivel: el que vigila ese trabajo y decide sobre él. Cuando Jael se pregunta cuánto va a recordar mañana, sube un parte (monitoreo); cuando decide dejar el resumen y pasar a tarjetas, baja una decisión (control). Todo lo que pasa en una sesión vive en uno de los dos pisos, y la nota la produce el de abajo, pero cuánto rinde cada hora lo decide el de arriba."},{"q":"¿Por qué se dice que la gente no decide mal, sino que decide bien sobre datos malos?","ans":"Porque la falla casi nunca está en el timón: está en el vigía. Si el vigía sube «ya me lo sé», irse a dormir es la decisión correcta con ese dato; el problema es que el dato era falso, porque salía de la facilidad de releer y no de una prueba. Por eso regañar la decisión no arregla nada: lo que se audita es el parte, preguntando de dónde salió. Un parte que sale de producir con el material cerrado vale; uno que sale de la facilidad de tener el material delante, no."},{"q":"¿Qué hace válido o inválido un parte del vigía? Da dos ejemplos de cada lado.","ans":"El origen. Un parte vale cuando sale de producir la respuesta con el material cerrado: reproducirlo en hoja en blanco, o explicarlo sin mirar y que salga. No vale cuando sale de la facilidad de tener el material delante: «me suena» (reconocimiento: el examen pide producir, no saludar la página) y «lo leí tres veces» (esfuerzo: mide horas invertidas, no saber producido). La regla cabe en una línea: producir con material cerrado, sí; facilidad con material abierto, no."},{"q":"Jael dice «ya me lo sé» tras releer tres veces. ¿Qué se hace, paso a paso y por qué?","ans":"No se discute la sensación, porque es sincera y discutirla no la corrige. Se cierra el cuaderno, se toma una hoja en blanco y se reproduce lo estudiado sin mirar. Si sale, el parte queda confirmado y se duerme tranquila con razón. Si no sale, aparecieron los huecos que la relectura escondía, y el repaso siguiente empieza exactamente por lo que falló, no por releer todo. Y lo que salga se apunta en el registro, porque la brecha de hoy entrena al vigía de mañana."},{"q":"¿Qué es la brecha, cómo se apunta y para qué sirve un registro donde la brecha no es cero?","ans":"La brecha es la diferencia entre lo que el vigía predijo y lo que salió en la comprobación. Se apunta en cuatro columnas: predicción, fecha, resultado, brecha; dos líneas por prueba. Y un registro con brecha no es un registro fracasado: es el único que enseña algo. La meta es brecha vista, no brecha cero: quien descubre que se pasa de optimista en Ciencias por diez puntos ya puede descontarlo, y ese descuento vale más que cien buenas intenciones de estudiar más."},{"q":"¿Por qué esta etapa es la puerta del Estudio Mayor entero?","ans":"Porque el Estudio Mayor son más de veinte materias, y todas se estudian con la misma máquina: la propia cabeza. Esta etapa enseña a vigilar esa máquina: separar el trabajo (nivel objeto) de la vigilancia (metanivel), auditar los partes del vigía por su origen, y darle al timón datos comprobados en vez de sensaciones. Quien tiene eso estudia cualquier materia a mitad de precio; quien no lo tiene, estudia a ciegas todas. Por eso va primero, y por eso su registro lo heredan las etapas y materias que siguen."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

