function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"La noche antes del examen de Ciencias, Jael relee el cuaderno tres veces. El texto corre fácil, dice «ya me lo sé» y cierra el cuaderno para irse a dormir."},{"txt":"Angelly estudia con resumen, a los cinco minutos pasa a tarjetas, a los cinco vuelve al cuaderno, después prueba un video. Al final de la hora dice que ninguna técnica le funciona."},{"txt":"Un vendedor ofrece a la familia un curso de «técnicas de estudio y súper aprendizaje» por L 3,500: subrayado de colores, mapas mentales, relectura guiada y testimonios de alumnos felices."},{"txt":"En un aula que usa M.E.T.A.S, la maestra explica, pregunta «¿entendieron?», todos asienten, y el examen de la semana siguiente sale mal. La maestra concluye que los alumnos le mintieron."},{"txt":"El autor lee el compendio de la Ruta de la Ley completo en dos tardes y siente que domina la pirámide normativa. Tres días después intenta explicarla y se le mezclan dos escalones."},{"txt":"Alguien de la casa descubre que puede voltear todas las flashcards de una misión sin leerlas, y la barra de XP sube igual."},{"txt":"Una tarde de estudio sale redonda: con música, sin trabas, todo fluye. La prueba corta del día siguiente sale peor que la de la semana anterior, que se había sentido torpe."},{"txt":"La familia arranca el registro del vigía: cada quien apunta su predicción antes de cada prueba de la semana, y después el resultado real. La primera semana casi nadie acierta."}];
const critCaseQuestions=["1. ¿Qué parte subió el vigía en este caso, y de dónde salió ese parte: de producir con el material cerrado o de la facilidad de tenerlo delante?","2. ¿Qué decidió el timón (o qué está por decidir), y decidió con un dato comprobado o con una sensación?","3. ¿Dónde está el parte falso, si lo hay, y qué pista lo fabricó: la fluidez, el «me suena», las horas invertidas?","4. ¿Qué se comprueba a cuaderno cerrado, y qué se apunta en el registro para que el vigía aprenda de este caso?"];
const critCaseGuides=["Se busca primero el parte: la frase del vigía («ya me lo sé», «ninguna técnica me funciona», «esto fluye») y se le pregunta el origen. Un parte que sale de producir la respuesta con el material cerrado vale; uno que sale de la facilidad de releer, de reconocer la página o de contar horas, no vale, por fuerte y sincero que se sienta. La sensación no se regaña: se audita.","Después se mira la decisión. El timón casi siempre decide razonablemente CON EL DATO QUE TIENE: dormir si «ya lo sé», cambiar de técnica si «no funciona». Por eso el diagnóstico no es «decidió mal» sino «decidió sin parte comprobado». Una decisión de control sin monitoreo detrás es un volantazo, aunque salga bien.","El parte falso se localiza nombrando la pista que lo fabricó. La fluidez: el texto corre fácil y la facilidad se factura como saber. El reconocimiento: «me suena» no es poder producirlo. El esfuerzo: «lo leí tres veces» mide horas, no resultado. Nombrar la pista importa porque la vacuna es distinta para cada una, y la etapa 2 de esta ruta las caza una por una.","Todo caso termina igual: una comprobación con el material cerrado (hoja en blanco, explicarlo sin mirar, la prueba corta) y dos líneas en el registro: qué se predijo, qué salió, cuánta brecha quedó. La meta de la casa no es acertar la predicción: es ver la brecha, porque el sesgo conocido se descuenta y el desconocido se paga en el examen."];

const critErrorBank=[{"txt":"\"Releí todo el cuaderno tres veces, así que ya me lo sé\".","g1":"La relectura produce fluidez, y el vigía factura esa facilidad como saber. El parte sale de tener el material delante, que es justo el origen que no vale.","g2":"Se comprueba con la hoja en blanco: si sale, confirmado y a dormir; si no sale, el repaso empieza por lo que falló. El «ya me lo sé» no se discute: se comprueba."},{"txt":"\"Sentí la clase facilísima, o sea que aprendí muchísimo\".","g1":"La sensación durante el estudio mide la comodidad del momento, y el aprendizaje se mide después y con el material cerrado. Las dos medidas pueden ir al revés.","g2":"La sesión se califica al día siguiente, con la comprobación. En el registro, la columna del resultado siempre se llena un día después que la de la predicción."},{"txt":"\"Esta técnica me aburre, mejor cambio a otra\".","g1":"Cambiar de técnica es una decisión del timón, y aquí no hay ningún parte comprobado detrás: hay aburrimiento. Es un volantazo, no gobierno.","g2":"Antes de cambiar se pide el parte: una comprobación pequeña con el material cerrado. Si la técnica rinde, se queda aunque aburra; si no rinde, se cambia con causa."},{"txt":"\"Los niños me dijeron que entendieron; me mintieron\".","g1":"Nadie mintió: el «¿entendieron?» le pide a cada vigía un parte, y cada vigía contesta con la pista que tiene: la explicación se dejó seguir. Eso es reconocimiento, no recuerdo.","g2":"La pregunta útil obliga a producir: «cierren el cuaderno y escríbanme los dos pasos». Cinco minutos de eso valen más que cualquier asentimiento."},{"txt":"\"Llené la barra de XP, ya domino la misión\".","g1":"Los XP son un vigía externo: un indicador indirecto del recorrido. Como todo indicador indirecto, se puede engañar, y quien lo engaña se engaña.","g2":"El dominio lo mide la evaluación con el material cerrado, no la barra. Saber qué mide cada indicador de la casa es la misma destreza que auditar al propio vigía."},{"txt":"\"No apunto predicciones porque casi nunca acierto\".","g1":"Acertar no es la meta: la meta es la brecha vista. Un registro donde nadie falla no enseña nada; el error apuntado es el dato más útil que produce la casa.","g2":"El vigía solo se entrena comparando predicción contra resultado. Quien no apunta porque falla se queda con el fallo y sin el aprendizaje, que es pagar el precio sin llevarse el producto."}];

const critDecisionBank=["Jael dice «ya me lo sé» a las nueve de la noche: ¿se le discute la sensación, se le manda releer, o se le pone la hoja en blanco? ¿Y qué se hace con lo que salga?","Angelly quiere cambiar de técnica por tercera vez en la misma hora: ¿se le deja, se le prohíbe, o se le pide algo antes de cambiar? ¿Qué exactamente?","El vendedor del curso de L 3,500 espera respuesta esta semana: ¿qué pregunta única se le hace, y qué respuesta lo descarta?","La maestra quiere saber si la clase entendió: ¿qué pregunta hace en los últimos cinco minutos, y por qué esa y no «¿entendieron?»?","El papá cierra el compendio con sensación de dominio: ¿qué comprobación se hace antes de darlo por estudiado, y cuándo?","Alguien voltea flashcards sin leerlas y la barra sube: ¿qué se cambia, la barra o la costumbre? ¿Por qué?","La sesión de hoy fluyó perfecta: ¿cuándo y con qué se califica de verdad?","La familia arranca el registro del vigía: ¿qué cuatro columnas lleva, y cuál es la meta de la primera semana?"];
const critDecisionGuide='La decisión correcta en esta etapa sigue siempre el mismo orden: primero se nombra el dato que cruza la frontera y de dónde viene; después se escribe la comprobación como lista permitida y se pone del lado del servidor, que es el que el usuario no puede editar; después se decide qué pasa cuando la comprobación no se puede hacer, y ahí se falla cerrado, nunca en silencio; y al final se rompe la comprobación a propósito para ver que de verdad se pone roja. Si el fallo no se puede oír, todavía no está resuelto.';

const critCompareBank=[{"a":"Comprobar con hoja en blanco antes de dormir.","b":"Confiar en el «ya me lo sé» de la relectura.","ga":"Caso A: el parte queda confirmado o desmentido esta noche, cuando arreglarlo cuesta diez minutos sobre lo fallado.","gb":"Caso B: el parte se comprueba mañana en el examen, que es el lugar más caro para descubrir un hueco."},{"a":"Cambiar de técnica después de una comprobación pequeña.","b":"Cambiar de técnica por aburrimiento.","ga":"Caso A: el cambio tiene causa y deja un dato: la técnica anterior rendía o no rendía, y quedó apuntado.","gb":"Caso B: se gira el timón sin parte, y al final de la hora «ninguna técnica funciona» porque ninguna se midió."},{"a":"Preguntar «cierren el cuaderno y escriban los dos pasos».","b":"Preguntar «¿entendieron?».","ga":"Caso A: obliga a producir con el material cerrado, que es la única lectura fiable, y dice exactamente qué reexplicar.","gb":"Caso B: pide partes de vigías engañados por la explicación fluida, y todos asienten con sinceridad y sin saber."},{"a":"Apuntar la predicción y mirar la brecha.","b":"Estudiar sin registro y fiarse de la memoria del vigía.","ga":"Caso A: en un mes la casa sabe quién es optimista, en qué materia y por cuánto, y el timón lo descuenta.","gb":"Caso B: el vigía nunca se entera de sus errores, y el mismo «ya me lo sé» falso vuelve cada semana."}];

const critCauseBank=[{"cause":"Se estudia releyendo, y el vigía factura la facilidad como saber.","guide":"El parte falso llega al timón, la decisión razonable se toma sobre datos malos, y el hueco aparece en el examen: el lugar más caro y más tarde posible para descubrirlo."},{"cause":"El timón cambia de técnica sin ninguna comprobación.","guide":"Ninguna técnica llega a medirse, todas aburren antes de rendir, y al final de la hora la conclusión es «nada me funciona», que es falsa pero queda apuntada en la cabeza."},{"cause":"Nadie apunta predicciones.","guide":"No hay brecha que mirar, el vigía repite sus sesgos intactos, y cada semana se vuelve a pagar el mismo error como si fuera nuevo."},{"cause":"La sesión se califica por la sensación al terminarla.","guide":"Las tardes cómodas se premian y las tardes fértiles e incómodas se castigan, así que el timón aprende a elegir exactamente las técnicas que menos rinden."},{"cause":"La pregunta de cierre del aula mide asentimiento.","guide":"La maestra sale con partes falsos de treinta vigías, reexplica lo que no hacía falta y deja intacto el hueco real, que aparece completo el día del examen."},{"cause":"Se optimizan los XP en vez del dominio.","guide":"La barra se llena, el indicador deja de significar, y el día de la evaluación con material cerrado la brecha entre barra y cabeza sale a cobrar entera."}];
const critEffectBank=[{"effect":"El examen dejó de dar sorpresas: lo que el vigía decía, salía.","guide":"Cada «ya me lo sé» se comprobó con el cuaderno cerrado antes de darlo por bueno, y el repaso siempre empezó por lo que la hoja en blanco desmintió."},{"effect":"Angelly se quedó con una técnica y empezó a rendirle.","guide":"Antes de cada cambio se pidió una comprobación pequeña. La técnica que rendía se quedó aunque aburriera, y el aburrimiento se le pasó al ver la brecha encoger."},{"effect":"La familia sabe quién es optimista, en qué materia y por cuánto.","guide":"Cuatro columnas durante un mes: predicción, fecha, resultado, brecha. Nadie mejoró la puntería la primera semana, y no hacía falta: la meta era ver el sesgo."},{"effect":"La maestra supo qué reexplicar antes del examen.","guide":"Cambió el «¿entendieron?» por «cierren el cuaderno y escríbanme los dos pasos». Cinco minutos de producción con material cerrado le dijeron lo que treinta asentimientos escondían."},{"effect":"El curso de L 3,500 se declinó sin pelear.","guide":"Se hizo la pregunta única: ¿en qué minuto el alumno produce la respuesta con el material cerrado? La respuesta fue el silencio de siempre, y con eso alcanzó."},{"effect":"La barra de XP volvió a significar algo.","guide":"Se acordó en familia qué mide cada indicador: XP el recorrido, la evaluación el dominio. Engañar la barra dejó de ser gracia cuando quedó claro a quién se engañaba."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 La sesión sobre la mesa · Forma ${cf} · El vigía y el timón · Ruta de la Máquina que se Mira`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. La sesión sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué parte subió el vigía y de dónde salió, qué decidió el timón y con qué dato, y dónde está el parte falso con la pista que lo fabricó? Explica qué compruebas a cuaderno cerrado y qué apuntas en el registro.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos comprueba el parte antes de decidir? 2. ¿Por qué no son la misma decisión?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0 a 20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 La sesión sobre la mesa: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. La sesión sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué parte subió el vigía y de dónde salió, qué decidió el timón y con qué dato, y dónde está el parte falso con la pista que lo fabricó? Explica qué compruebas a cuaderno cerrado y qué apuntas en el registro.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos comprueba el parte antes de decidir? 2. ¿Por qué no son la misma decisión?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>La sesión sobre la mesa El vigía y el timón · Ruta de la Máquina que se Mira · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · La sesión sobre la mesa · El vigía y el timón · Ruta de la Máquina que se Mira · Etapa 1 · Estudio Mayor</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: La sesión sobre la mesa · El vigía y el timón · Ruta de la Máquina que se Mira · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"🗺️","label":"El plan","text":"Antes de abrir el cuaderno: <strong>qué toca y con qué técnica</strong>. Es la primera decisión del timón. <strong>Se cae:</strong> cuando el plan lo decide la costumbre («siempre empiezo releyendo») y no un dato de la semana pasada."},{"y":"2","icon":"📝","label":"La predicción","text":"El parte del vigía <strong>por escrito y antes de empezar</strong>: «voy a poder reproducir tanto». <strong>Sirve para:</strong> tener con qué comparar después. <strong>Se cae:</strong> no apuntándola, que es lo normal y por eso casi nadie tiene registro."},{"y":"3","icon":"🏗️","label":"El estudio","text":"El nivel objeto hace <strong>el trabajo</strong>: lee, resuelve, memoriza. <strong>Ojo:</strong> este momento produce la nota, pero cuánto rinde cada hora lo deciden los otros seis. Estudiar más no arregla lo que la vigilancia hace mal."},{"y":"4","icon":"🔭","label":"El parte del vigía","text":"A mitad de sesión: <strong>«¿cómo voy?»</strong>. <strong>La pregunta clave:</strong> ¿de dónde sale este parte? Si sale de producir con el material cerrado, vale. Si sale de que el texto corre fácil, es la falla habitual en camino."},{"y":"5","icon":"⚓","label":"La decisión del timón","text":"<strong>Seguir, cambiar de técnica o parar.</strong> Ninguna es mala en sí: son malas sin parte comprobado. <strong>Regla de la casa:</strong> el timón no gira sin dato; cambiar por aburrimiento es un volantazo."},{"y":"6","icon":"📄","label":"La comprobación","text":"Al final: <strong>cuaderno cerrado, hoja en blanco, reproducir</strong>. Es la única lectura fiable del propio saber. <strong>Se cae:</strong> saltándosela porque la sensación ya dijo que todo está bien, que es exactamente cuando más hace falta."},{"y":"7","icon":"📏","label":"La brecha","text":"Lo predicho contra lo que salió, <strong>apuntado en el registro</strong>. <strong>La meta:</strong> brecha vista, no brecha cero. Este momento alimenta el plan de la próxima sesión, y así el círculo se cierra: el vigía de hoy entrena al de mañana."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(comprobo){sfx(comprobo?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(comprobo){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">📝</span><span class="ms-text"><strong>Cerraste el cuaderno y escribiste lo que sabías:</strong> salieron dos huecos que la relectura no había enseñado. El parte decía «todo», y la hoja en blanco dijo «casi todo».</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">⚓</span><span class="ms-text"><strong>El timón decidió con datos:</strong> diez minutos sobre los dos huecos, la brecha apuntada en el registro, y a dormir con el parte confirmado. El examen no dio ninguna sorpresa.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">😴</span><span class="ms-text"><strong>Confiaste en la sensación:</strong> era fuerte y era sincera. También salía de la facilidad de releer, que es exactamente el origen que no vale.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📄</span><span class="ms-text"><strong>El examen pidió producir, no reconocer:</strong> los huecos aparecieron delante de la hoja, que es el lugar más caro para descubrirlos. La decisión de dormir era razonable; el parte era falso, y nadie lo auditó.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"niveles":{"nombre":"Los dos pisos","icon":"🏗️","estructura":{"title":"Qué es","info":"• El mapa de <strong>Nelson y Narens (1990)</strong><br>• Abajo, el <strong>nivel objeto</strong>: lee, resuelve, memoriza<br>• Arriba, el <strong>metanivel</strong>: vigila el trabajo y decide sobre él"},"funcion":{"title":"Cómo se reconoce","info":"• Pregunta de bolsillo: ¿esta frase <strong>hace la tarea</strong> o <strong>habla de la tarea</strong>?<br>• «Resuelvo la división»: piso de abajo<br>• «Voy mal en divisiones»: piso de arriba"},"enfermedades":{"title":"Dónde se cae","info":"• Creyendo que estudiar es <strong>solo el piso de abajo</strong><br>• Echándole horas al trabajo cuando la falla está en la vigilancia<br>• Confundiendo los dos oficios de arriba: el parte no es la decisión"},"cuidados":{"title":"En esta casa","info":"• Toda sesión se relata <strong>con el vocabulario de los dos pisos</strong><br>• La hoja del vigía separa qué fue monitoreo y qué fue control<br>• Y la nota se explica mirando los dos, no solo las horas"}},"vigia":{"nombre":"El vigía (monitoreo)","icon":"🔭","estructura":{"title":"Qué es","info":"• La corriente que <strong>sube</strong>: información de cómo va el trabajo<br>• «¿Cuánto sé?», «esto está flojo», «ya me lo sé»<br>• Todo parte del vigía <strong>puede ser falso</strong>"},"funcion":{"title":"Cómo se reconoce","info":"• Un parte vale por <strong>su origen</strong>, no por su fuerza<br>• De producir con el material cerrado: <strong>vale</strong><br>• De la facilidad de tener el material delante: <strong>no vale</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• La <strong>fluidez</strong>: el texto corre fácil y se factura como saber<br>• El <strong>«me suena»</strong>: reconocer no es recordar<br>• Las <strong>horas</strong>: «lo leí tres veces» mide esfuerzo, no resultado"},"cuidados":{"title":"En esta casa","info":"• El «ya me lo sé» <strong>no se discute: se comprueba</strong><br>• Cuaderno cerrado, hoja en blanco, reproducir<br>• Y el parte comprobado se apunta, porque entrena al vigía de mañana"}},"timon":{"nombre":"El timón (control)","icon":"⚓","estructura":{"title":"Qué es","info":"• La corriente que <strong>baja</strong>: decisiones sobre el trabajo<br>• Las tres clásicas: <strong>seguir, cambiar de técnica, abandonar</strong><br>• También: qué repasar primero, cuándo parar, cómo repartir la hora"},"funcion":{"title":"Cómo se reconoce","info":"• Toda frase que <strong>cambia lo que se hace</strong> es del timón<br>• La pregunta de auditoría: ¿esta decisión <strong>con qué dato</strong> se tomó?<br>• Con parte comprobado: gobierno. Sin parte: volantazo"},"enfermedades":{"title":"Dónde se cae","info":"• Cambiando de técnica <strong>por aburrimiento</strong><br>• Repasando lo que <strong>se siente</strong> flojo sin comprobar nada<br>• Parando cuando lo decide <strong>el sueño</strong> y no una regla"},"cuidados":{"title":"En esta casa","info":"• El timón <strong>no gira sin parte</strong>: comprobación pequeña antes de cambiar<br>• La técnica que rinde se queda <strong>aunque aburra</strong><br>• Y la regla de parada se escribe antes de empezar la sesión"}},"brecha":{"nombre":"La brecha y el registro","icon":"📏","estructura":{"title":"Qué es","info":"• La diferencia entre <strong>lo predicho y lo que salió</strong><br>• Vive en el registro: <strong>predicción, fecha, resultado, brecha</strong><br>• Es el dato con que el vigía aprende de sus errores"},"funcion":{"title":"Cómo se reconoce","info":"• Antes de la prueba se apunta el parte: «creo que saco tanto»<br>• Después se apunta lo real, <strong>sin maquillar</strong><br>• La resta de los dos es la brecha, y se mira por semanas"},"enfermedades":{"title":"Dónde se cae","info":"• No apuntando la predicción, <strong>que es lo normal</strong><br>• Apuntando solo cuando se acierta, que arruina el dato<br>• Buscando brecha cero, cuando la meta es <strong>brecha vista</strong>"},"cuidados":{"title":"En esta casa","info":"• Dos líneas por prueba, <strong>cuatro columnas</strong>, y nada más<br>• La meta de la primera semana: descubrir <strong>el sesgo de cada quien</strong><br>• Este registro lo heredan la etapa 6 y la materia de predicción del Estudio Mayor"}}};
