// misión. Las preguntas se contestan con los textos delante: son examen de
// lectura, no de memoria, que es exactamente la lección de la etapa.
const lectComprensionBank=[{"t":"Borges","q":"¿Qué guardaba Ibarra en su libreta verde?","o":["a) Un diario de la vida del colegio","b) Dos columnas: lo que creía que iba a poder y lo que efectivamente pudo","c) Las respuestas de los exámenes copiadas","d) Los apuntes de historia pasados en limpio"],"c":1},{"t":"Borges","q":"¿Qué diferencia había entre el narrador e Ibarra frente a los exámenes?","o":["a) El narrador estudiaba menos horas que Ibarra","b) Ibarra era más inteligente y por eso no fallaba","c) Al narrador sus notas lo sorprendían siempre; a Ibarra no lo sorprendió nunca nada","d) Ibarra copiaba las predicciones de otros"],"c":2},{"t":"Borges","q":"¿Qué reglas encontró el narrador anotadas en los márgenes de la libreta?","o":["a) «Me suena: no vale», «corrió fácil de releído: descontar» y «sin sacarlo con el cuaderno cerrado, no hay parte»","b) «Estudiar siempre de noche» y «repasar dos veces»","c) Las fechas de todos los exámenes del año","d) Los nombres de los profesores más exigentes"],"c":0},{"t":"Borges","q":"¿Con qué estudios entendió el narrador, años después, lo que Ibarra hacía?","o":["a) Con los boletines del colegio que conservaba","b) Con un manual de agrimensura","c) Con las cartas de la hija de Ibarra","d) Con Flavell (1979), Nelson y Narens (1990) y Koriat (1997)"],"c":3},{"t":"Borges","q":"Según el cierre del cuento, ¿cuál era la verdadera diferencia entre los dos?","o":["a) Una diferencia de espejos: el narrador se miraba en el que adula, Ibarra en el que mide","b) Una diferencia de inteligencia a favor de Ibarra","c) Que Ibarra tenía mejores cuadernos","d) Que el narrador no sabía leer despacio"],"c":0},{"t":"Cervantes","q":"¿Qué presumía el bachiller en la venta?","o":["a) Haber ganado una apuesta en Salamanca","b) Que había pasado sus cuadernos tres veces enteras y todo le sonaba como cosa propia","c) Saber tañer las campanas de la iglesia","d) Conocer de memoria más de veinte romances"],"c":1},{"t":"Cervantes","q":"¿Qué concierto le propuso la moza al bachiller?","o":["a) Que le enseñara a leer a cambio de la cena","b) Que recitara con los cuadernos abiertos","c) Apostar la cena: ella le guardaba los cuadernos y él decía de memoria lo que decía tener","d) Que cantara un romance con ella"],"c":2},{"t":"Cervantes","q":"¿Cómo aprendía la moza sus romances?","o":["a) Leyéndolos muchas veces hasta que le sonaran","b) Pidiendo que se los soplaran verso a verso","c) Escuchándolos una sola vez, porque tenía memoria prodigiosa","d) Cantándolos con el papel guardado, volviendo donde se trababa, y contando antes y después cuántas coplas sacaba enteras"],"c":3},{"t":"Cervantes","q":"¿Qué respondió el ventero al «es que lo he leído tres veces» del bachiller?","o":["a) Que su mula había pasado tres veces por el puente y no por eso sabía hacer puentes","b) Que tres veces eran pocas y hacían falta seis","c) Que leyera en voz más baja","d) Que los cuadernos estaban mal escritos"],"c":0},{"t":"Cervantes","q":"¿Qué regla escribió el bachiller con carbón sobre la tabla de sus cuadernos?","o":["a) No volver a apostar cenas con desconocidos","b) No decir «ya lo tengo» sin haberlo dicho todo con el cuaderno cerrado, y apuntar antes y después para que la diferencia fuera su maestra","c) Estudiar solamente de día y en silencio","d) No leer nunca en las ventas"],"c":1},{"t":"Harari","q":"Según el ensayo, ¿cuál es la segunda rareza de nuestra especie?","o":["a) Ser la única especie capaz de equivocarse acerca de lo que sabe","b) Ser la única especie que caza en grupo","c) Ser la única especie que usa signos","d) Ser la única especie que duerme poco antes de los exámenes"],"c":0},{"t":"Harari","q":"¿Quién le puso nombre al campo, y con qué dos publicaciones?","o":["a) Nelson y Narens, con dos artículos de 1990","b) Koriat, con un experimento de 1997","c) John Flavell, con un capítulo de 1976 y un artículo de 1979 en American Psychologist","d) Dunlosky, con una monografía de 2013"],"c":2},{"t":"Harari","q":"¿Qué describe el mapa de Nelson y Narens (1990)?","o":["a) Las diez técnicas de estudio ordenadas por evidencia","b) Dos niveles, objeto y meta, con información que sube (monitoreo) y decisiones que bajan (control)","c) Las etapas del desarrollo según Piaget","d) La memoria de corto y largo plazo"],"c":1},{"t":"Harari","q":"¿Qué encontró la monografía de Dunlosky y sus colegas (2013)?","o":["a) Que subrayar con colores mejora la retención","b) Que todas las técnicas rinden igual si se usan con constancia","c) Que releer funciona mejor que probarse","d) Que de diez técnicas revisadas, releer y subrayar quedaron entre las de menor utilidad, y probarse a uno mismo entre las mejores"],"c":3},{"t":"Harari","q":"Según el ensayo, ¿qué es la sensación de saber?","o":["a) Una lectura directa de la memoria","b) Un reflejo del esfuerzo invertido, y por eso fiable","c) Una apuesta fabricada con pistas indirectas, como la fluidez y la familiaridad (Koriat, 1997)","d) Una emoción sin ninguna función"],"c":2},{"t":"Entrevista","q":"En los experimentos que Flavell relata, ¿qué hacían los niños de preescolar?","o":["a) Se negaban a estudiar las listas","b) Decían «ya estoy listo» con total sinceridad, y al pedirles la lista fallaban","c) Recordaban más elementos que los mayores","d) Pedían estudiar más tiempo del necesario"],"c":1},{"t":"Entrevista","q":"¿Con qué libro empezó la carrera de Flavell, según la entrevista?","o":["a) Una sistematización de la psicología del desarrollo de Jean Piaget, publicada en 1963","b) Un manual de metacognición para maestros","c) Una biografía de Nelson y Narens","d) Un estudio sobre la memoria de los adultos"],"c":0},{"t":"Entrevista","q":"¿Dónde publicó Flavell el artículo de 1979 que bautizó el campo?","o":["a) En la revista Nature","b) En un capítulo de un libro sobre inteligencia","c) En los anales de la Universidad de Stanford","d) En la revista American Psychologist"],"c":3},{"t":"Entrevista","q":"¿Cómo explica Flavell la diferencia entre monitoreo y control?","o":["a) El monitoreo decide y el control informa","b) Del nivel objeto sube información (monitoreo) y del metanivel bajan decisiones (control): continuar, cambiar de estrategia, terminar","c) Son dos nombres de la misma corriente","d) El monitoreo es de los niños y el control de los adultos"],"c":1},{"t":"Entrevista","q":"¿Cuáles son los tres consejos que Flavell le daría a la nieta de Punset?","o":["a) Releer más veces, subrayar con colores y dormir bien","b) Estudiar en grupo, pedir ayuda y no rendirse","c) Saber que la sensación de la relectura es una trampa documentada, comprobar con el cuaderno cerrado, y apuntar predicción y resultado en un registro","d) Cambiar de técnica cada semana hasta encontrar la propia"],"c":2},{"t":"Quintero y Gala","q":"¿Qué dato trae Quintero sobre el nombre del asunto?","o":["a) Que se llama metacognición y se lo puso el psicólogo Flavell en un artículo de 1979","b) Que se llama memoria y lo estudió Séneca","c) Que no tiene nombre todavía","d) Que lo bautizó Gala en una columna"],"c":0},{"t":"Quintero y Gala","q":"¿Con qué imagen traduce Gala el mapa de los dos pisos?","o":["a) Un barco con dos cubiertas","b) Un teatro con escenario y palco","c) La casa de Córdoba con azotea: abajo, entre las macetas, se ven flores; para ver qué hay que regar hay que subir","d) Una venta con dos plantas"],"c":2},{"t":"Quintero y Gala","q":"¿Qué ley aprendió Gala en los ensayos de «Anillos para una dama» (1973)?","o":["a) Que las escenas salen mejor con el cuaderno en la mano","b) Que los actores no deben cenar antes del estreno","c) Que el teatro no se puede ensayar","d) Que el actor que no ha soltado el papel no se sabe el papel: se sabe el gusto de leerlo"],"c":3},{"t":"Quintero y Gala","q":"¿Qué revisión de técnicas menciona Quintero?","o":["a) Una tesis de Salamanca sobre romances","b) La del año 2013: diez técnicas, con releer y subrayar entre las que menos rinden y examinarse uno mismo entre las que más","c) Un estudio de 1990 sobre el teatro","d) Una encuesta de la radio entre estudiantes"],"c":1},{"t":"Quintero y Gala","q":"¿Cuál es el aforismo con que Gala cierra la conversación?","o":["a) Que el fracaso sin apuntar es solamente dolor","b) Que las verdades caras vienen con orquesta","c) Que a Troylo le debe un libro entero","d) Que saber es poder decirlo con el libro cerrado, y que la sabiduría empieza donde el espejo deja de adular"],"c":3}];
const lectCompletarBank=[{"t":"las cinco","q":"Flavell bautizó el campo en su artículo de ___, publicado en American Psychologist.","a":"1979"},{"t":"las cinco","q":"El mapa de los dos niveles lo publicaron Nelson y Narens en ___.","a":"1990"},{"t":"Harari","q":"Koriat mostró en 1997 que los juicios de aprendizaje se construyen con ___ indirectas.","a":"pistas"},{"t":"Borges","q":"La libreta verde de Ibarra tenía en cada hoja dos ___.","a":"columnas"},{"t":"Cervantes","q":"El ventero: su mula había pasado tres veces por el ___ y no por eso sabía hacer puentes.","a":"puente"},{"t":"Harari","q":"La monografía que revisó diez técnicas de estudio, de Dunlosky y sus colegas, es del año ___.","a":"2013"},{"t":"Entrevista","q":"Flavell publicó su gran libro sobre la psicología de Piaget en ___.","a":"1963"},{"t":"Entrevista","q":"Eduard Punset dirigió y presentó en TVE el programa de divulgación científica ___.","a":"Redes"},{"t":"Quintero y Gala","q":"Gala ganó el Premio Planeta de 1990 con «El manuscrito ___».","a":"carmesí"},{"t":"Quintero y Gala","q":"Para Gala, la sabiduría empieza donde el ___ deja de adular.","a":"espejo"}];
const lectAnalisisBank=[{"q":"1. Las cinco lecturas llegan al mismo asunto por cinco puertas. Explica qué hace cada voz que las otras no pueden hacer, y qué se perdería leyendo solo una.","guia":"El cuento convierte el concepto en un objeto heredado, la libreta de dos columnas, y en una vergüenza personal: el narrador nunca contó las veces que su seguridad mintió, y esa confesión llega más hondo que cualquier definición. El capítulo lo vuelve escena y risa: la mula del puente y la moza que cuenta coplas hacen memorable en dos frases lo que una tabla explica en diez. El ensayo pone la escala de especie y encadena los estudios con sus años (1976, 1979, 1990, 1997, 2013), que es lo que permite comprobar. La entrevista sienta al personaje real de la etapa, Flavell, frente a preguntas con su biografía delante, y de paso enseña quién fue Punset. Y la conversación baja el tema al habla viva de la noche: Quintero trae los números y Gala los devuelve como imágenes (la azotea, el espejo del recibidor). Leyendo solo una se tendría, según el caso, melancolía sin datos, risa sin método, datos sin imagen, biografía sin escena o poesía sin cifras. Las cinco juntas dan lo mismo por cinco caminos."},{"q":"2. La libreta de Ibarra: explica qué son las dos columnas, qué son las notas del margen, y por qué el cuento dice que la libreta era un instrumento y no un diario.","guia":"La primera columna es la predicción (el juicio de aprendizaje puesto por escrito antes de la prueba: qué nota sacaría, cuántos temas repetiría) y la segunda es el resultado real. Juntas producen la brecha, que al principio del cuento es ancha (Ibarra adolescente también se creía más de lo que era) y con los años se angosta: la brecha vista se va corrigiendo. Las notas del margen son las reglas de auditoría de los partes: «me suena: no vale» (el reconocimiento no es recuerdo), «corrió fácil de releído: descontar» (la fluidez de la relectura es una pista falsa), «sin sacarlo con el cuaderno cerrado, no hay parte» (la única lectura fiable es la producción con el material cerrado), y «en historia restar cinco» (el sesgo conocido se descuenta). Es instrumento y no diario porque no registra sentimientos sino mediciones: sirve para navegar, como una brújula a la que se le conoce el desvío, y por eso el cuento dice que Ibarra podía navegar con ella."},{"q":"3. La moza de la venta no sabe leer y estudia mejor que el bachiller. Explica su método con el vocabulario técnico de la etapa y di por qué es superior.","guia":"El método de la moza tiene las tres piezas del protocolo de la casa sin saber sus nombres. Canta los romances con el papel guardado: eso es recuperación con el material cerrado, la única lectura fiable del vigía. Donde se traba, allí vuelve: usa el fallo como información para el timón, que decide qué repasar con un dato comprobado y no con una sensación. Y antes de cantar delante de gente se dice cuántas coplas sacará enteras, y después cuenta las que salieron: eso es predicción y brecha, el registro con que se entrena el vigía («que así sé de mí lo que hay, y no lo que quisiera que hubiese»). El bachiller, en cambio, mide su saber por la facilidad de la relectura («todo le sonaba ya como cosa propia»), que es la pista falsa mejor documentada. Es superior porque sus partes salen de producir y los del bachiller de sentir, y la venta entera lo comprueba en un solo examen con los cuadernos bajo el paño."},{"q":"4. La frase del ventero sobre la mula que pasó tres veces por el puente: ¿qué pista engañosa retrata, y por qué la retrata tan bien?","guia":"Retrata la pista del esfuerzo: «lo he leído tres veces» como prueba de saber. La frase funciona porque separa con una imagen lo que la pista confunde: pasar por el saber (exponerse al material, invertir horas) y quedarse con el saber (poder producirlo). La mula acumuló pasadas por el puente igual que el bachiller acumuló relecturas, y ninguna de esas pasadas construyó la capacidad de hacer puentes, porque la exposición repetida sin recuperación no garantiza retención. La misión lo dice en su tabla de partes: «lo leí tres veces» sale del esfuerzo invertido y mide horas, no saber. Y la fuerza cómica importa: la risa fija la distinción mejor que el tecnicismo, que es exactamente el trabajo que la voz cervantina hace en esta sección y las otras voces no pueden hacer igual."},{"q":"5. El ensayo afirma que la sensación de saber es una apuesta y no una lectura. Explícalo con Koriat (1997) y con el ejemplo de la relectura.","guia":"El cerebro no tiene un medidor que consulte la memoria y devuelva un número: cuando alguien se pregunta si se sabe algo, el sistema infiere la respuesta a partir de indicios disponibles. Eso es lo que Koriat formuló en 1997: los juicios de aprendizaje se construyen con pistas, y las pistas pueden no tener relación con la retención real. La relectura es el ejemplo perfecto porque fabrica su propio engaño: cada pasada vuelve el texto más fluido, la fluidez se siente como dominio, y la sensación crece justo cuando el aprendizaje adicional es mínimo. Por eso la técnica más usada del mundo produce, hora tras hora, la ilusión de su propio éxito. La consecuencia práctica es la regla de la casa: un parte vale por su origen, no por su fuerza; si salió de tener el material delante, se descuenta; si salió de producir con el material cerrado, se acepta."},{"q":"6. El experimento de los niños que decían «ya estoy listo»: ¿qué demuestra y qué NO demuestra?","guia":"Demuestra que el monitoreo del propio saber es una capacidad aparte, que madura por su cuenta: los pequeños estudiaban con esfuerzo sincero, sentían estar listos y fallaban, mientras los mayores se calibraban bien. Demuestra también que un parte falso puede ser perfectamente honesto: los niños no mentían, su vigía todavía no sabía leer. No demuestra que los niños sean tontos ni que la sensación de saber sea inútil a toda edad: la calibración mejora con los años y con el registro que la vida va dando a golpes, y Flavell dice en la entrevista que se puede llegar antes y con menos golpes apuntando predicción y resultado. Tampoco demuestra que los adultos estén a salvo: el caso 5 de esta misión (el papá y el compendio) enseña que la fluidez de una buena lectura factura igual a cualquier edad. La lección es de método, no de edad: la sensación se audita por su origen."},{"q":"7. Explica por qué separar el monitoreo del control (Nelson y Narens, 1990) ordena la etapa entera, y aplícalo al caso de Jael y la relectura triple.","guia":"Porque localiza la falla. Si se mira la sesión como un todo, el diagnóstico queda vago («estudió mal»); con el mapa de los dos pisos se puede preguntar por separado qué subió y qué bajó. En el caso de Jael: el nivel objeto trabajó (releyó el cuaderno tres veces), el vigía subió «ya me lo sé» fabricado con la pista de la fluidez, y el timón, con ese parte, decidió parar y dormir. La decisión del timón era correcta dado el dato; el dato era falso. Ahí está la frase de la etapa: la gente no decide mal, decide bien sobre datos malos. Sin la separación, la familia regañaría la decisión (dormirse) o las horas (pocas), que no fueron el problema; con la separación, el arreglo es quirúrgico: auditar el parte con la hoja en blanco antes de dárselo al timón. Por eso el marco de 1990 es el esqueleto de la misión y de las cinco etapas que siguen."},{"q":"8. Dunlosky y sus colegas (2013) encontraron que las técnicas más usadas son de las que menos rinden. Explica la ironía con el vocabulario de la etapa: ¿qué pista las hace populares?","guia":"Las dos técnicas más populares, releer y subrayar, comparten una propiedad: se sienten bien mientras se hacen. La relectura vuelve el texto fluido y la fluidez se factura como dominio; el subrayado da sensación de trabajo visible sin obligar a producir nada con el material cerrado. Es decir: son populares precisamente por la pista falsa que fabrican, no a pesar de ella. Las técnicas mejor evaluadas, probarse a uno mismo y espaciar la práctica, se sienten peor: la prueba expone los huecos y el espaciado obliga a recuperar cuando ya cuesta. La sensación durante el estudio mide la comodidad del momento, y el aprendizaje se mide después y con el material cerrado: las dos medidas pueden ir al revés, como en el caso 7 de esta misión (la sesión que fluyó). La ironía a escala de especie es que elegimos las técnicas guiados por el instrumento averiado que esas mismas técnicas averían."},{"q":"9. La imagen del teatro de Gala (la escena que sale redonda con el cuaderno en la mano y se cae el día del estreno): tradúcela al vocabulario técnico de la etapa.","guia":"El ensayo con el cuaderno en la mano es estudio con el material abierto: la escena corre porque el texto está disponible, igual que el cuaderno releído corre fácil. El parte del vigía que sale de ahí («tenemos función», «ya me lo sé») está fabricado con la pista de la fluidez asistida, y es falso: mide el gusto de leer el papel, no la posesión del papel. El estreno es la prueba con el material cerrado, la única lectura fiable, y por eso la escena se cae: la recuperación real nunca se había ensayado. La ley de Gala («el actor que no ha soltado el papel no se sabe el papel») es la regla de la casa con otra ropa: saber no se siente, se comprueba con el cuaderno cerrado. Y la moraleja operativa es la del timón: el director que quiera partes verdaderos debe pedir ensayos sin cuaderno antes del estreno, igual que el estudiante debe pedirse la hoja en blanco antes del examen."},{"q":"10. Las dos entrevistas de esta sección son ficticias y lo declaran. Explica por qué esa etiqueta importa más en esta misión que en casi ninguna otra, y qué pasaría si se quitara.","guia":"Esta misión enseña a auditar partes: a preguntar de dónde sale cada «ya me lo sé» y a desconfiar de lo que suena bien sin comprobación. Una entrevista imaginada sin declarar sería exactamente un parte falso con buena cara: sonaría a documento y no lo es, y quien la citara estaría repitiendo sin verificar, que es el vicio que la etapa combate. La etiqueta convierte el artificio en herramienta honesta: dice que las personas son reales, que toda obra, fecha y cifra es comprobable, y que lo único inventado es la conversación, apoyándose además en un género real con historia, las entrevistas imposibles de la radio italiana de los años setenta. Si se quitara pasarían dos cosas: alguien atribuiría a Flavell, a Punset, a Quintero o a Gala palabras que nunca dijeron, y la casa quedaría fabricando la clase de fuente que enseña a cazar; y la lección quedaría desmentida por el ejemplo, que es la manera más eficaz de no enseñar nada."}];
const xpLect={c:new Set(),f:new Set()};

/* ---------- I. Comprensión lectora ---------- */
let lcIdx=0,lcSel=-1,lcDone=false;
function showLectC(){const cont=document.getElementById('lcQ');if(!cont)return;if(lcIdx>=lectComprensionBank.length){cont.textContent='🎉 ¡Comprensión lectora completada!';document.getElementById('lcOpts').innerHTML='';document.getElementById('lcProg').textContent='Las '+lectComprensionBank.length+' preguntas respondidas';unlockAchievement('lect_master');return;}const q=lectComprensionBank[lcIdx];document.getElementById('lcProg').textContent='Pregunta '+(lcIdx+1)+' de '+lectComprensionBank.length+' · '+q.t;cont.textContent=q.q;const opts=document.getElementById('lcOpts');opts.innerHTML='';lcSel=-1;lcDone=false;q.o.forEach((o,i)=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=o;b.onclick=()=>{if(lcDone)return;opts.querySelectorAll('.qz-opt').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');lcSel=i;sfx('click');};opts.appendChild(b);});}
function checkLectC(){if(lcIdx>=lectComprensionBank.length)return;if(lcSel<0)return fb('fbLC','Selecciona una respuesta.',false);lcDone=true;const opts=document.querySelectorAll('#lcOpts .qz-opt');if(lcSel===lectComprensionBank[lcIdx].c){opts[lcSel].classList.add('correct');fb('fbLC','¡Correcto! +2 XP',true);if(!xpLect.c.has(lcIdx)){xpLect.c.add(lcIdx);pts(2);}sfx('ok');}else{opts[lcSel].classList.add('wrong');opts[lectComprensionBank[lcIdx].c].classList.add('correct');fb('fbLC','Incorrecto. Vuelve al texto: la respuesta está ahí.',false);sfx('no');}setTimeout(()=>{lcIdx++;showLectC();},1700);}
function resetLectC(){sfx('click');lcIdx=0;showLectC();document.getElementById('fbLC').classList.remove('show');}

/* ---------- II. Completar ---------- */
let lfIdx=0;
function showLectF(){const cont=document.getElementById('lfQ');if(!cont)return;if(lfIdx>=lectCompletarBank.length){cont.innerHTML='🎉 ¡Las diez oraciones completadas!';document.getElementById('lfProg').textContent='Terminado';const inp=document.getElementById('lfInput');if(inp)inp.style.display='none';return;}const d=lectCompletarBank[lfIdx];document.getElementById('lfProg').textContent='Oración '+(lfIdx+1)+' de '+lectCompletarBank.length+' · '+d.t;cont.innerHTML=d.q.replace('___','<span class="blank">___</span>');const inp=document.getElementById('lfInput');if(inp){inp.style.display='';inp.value='';inp.classList.remove('eval-input-ok','eval-input-no');}}
function checkLectF(){if(lfIdx>=lectCompletarBank.length)return;const inp=document.getElementById('lfInput');const d=lectCompletarBank[lfIdx];if(!inp.value.trim())return fb('fbLF','Escribe tu respuesta.',false);const ok=isCpCorrect(inp.value,d.a);inp.classList.toggle('eval-input-ok',ok);inp.classList.toggle('eval-input-no',!ok);if(ok){fb('fbLF','¡Correcto! +2 XP',true);if(!xpLect.f.has(lfIdx)){xpLect.f.add(lfIdx);pts(2);}sfx('ok');}else{fb('fbLF','Todavía no. La respuesta esperada era: '+d.a,false);sfx('no');}setTimeout(()=>{lfIdx++;showLectF();document.getElementById('fbLF').classList.remove('show');},1900);}
function resetLectF(){sfx('click');lfIdx=0;showLectF();document.getElementById('fbLF').classList.remove('show');}

/* ---------- III. Análisis complejo (sin XP a propósito) ---------- */
let laIdx=0,laPautaVisible=false;
function showLectA(){const cont=document.getElementById('laQ');if(!cont)return;const d=lectAnalisisBank[laIdx];document.getElementById('laProg').textContent='Pregunta '+(laIdx+1)+' de '+lectAnalisisBank.length;cont.textContent=d.q;const p=document.getElementById('laPauta');p.innerHTML='<strong>Pauta:</strong> '+d.guia;p.style.display=laPautaVisible?'block':'none';document.getElementById('laTA').value='';}
function nextLectA(){sfx('click');laIdx=(laIdx+1)%lectAnalisisBank.length;showLectA();}
function prevLectA(){sfx('click');laIdx=(laIdx-1+lectAnalisisBank.length)%lectAnalisisBank.length;showLectA();}
function toggleLectAPauta(){sfx('click');laPautaVisible=!laPautaVisible;const p=document.getElementById('laPauta');p.style.display=laPautaVisible?'block':'none';const b=document.getElementById('btnLectAPauta');if(b)b.textContent=laPautaVisible?'🙈 Ocultar pauta':'👁 Ver pauta';}

/* ---------- impresión: cada lectura por separado ---------- */
// La etiqueta del estatus viaja SIEMPRE con el texto impreso. Con las dos
// entrevistas la etiqueta crece: además del pastiche hay que declarar que el
// encuentro nunca ocurrió, porque una hoja suelta se fotocopia y viaja sola,
// y una entrevista apócrifa sin declarar es un parte falso con buena cara.
const LECTURAS_IMPR={
  borges:{titulo:'La libreta de dos columnas',tipo:'Cuento, a la manera de Jorge Luis Borges'},
  cervantes:{titulo:'Donde se cuenta del bachiller que todo lo sabía, y del examen que le tomó la moza de la venta',tipo:'Capítulo, a la manera de Miguel de Cervantes Saavedra'},
  harari:{titulo:'El animal que cree que sabe',tipo:'Ensayo, a la manera de Yuval Noah Harari'},
  entrevista:{titulo:'El niño que decía «ya estoy listo»',tipo:'Entrevista imaginada con John H. Flavell, a la manera de Eduard Punset',ficcion:true},
  gala:{titulo:'La noche del que sabe que no sabe',tipo:'El Loco de la Colina: Jesús Quintero conversa con Antonio Gala (conversación imaginada)',ficcion:true},
};
function _etiquetaImpresa(meta){
  if(meta&&meta.ficcion){
    return '<div class="etiqueta"><strong>⚠️ Entrevista imaginada: ejercicio de estilo de la casa, en homenaje.</strong> El encuentro <strong>nunca ocurrió</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando las voces. Las personas son reales, <strong>toda obra, fecha y cifra citada es real y comprobable</strong>, y lo único inventado es la conversación.</div>';
  }
  return '<div class="etiqueta"><strong>⚠️ Ejercicio de estilo de la casa, en homenaje.</strong> Este texto <strong>NO es obra de ese autor</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando su voz, y se declara como pastiche. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro del texto es real y comprobable</strong>; el único artificio permitido es la voz.</div>';
}
function _hojaImpresa(titulo,cuerpo,pieExtra){
  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>${titulo} · El vigía y el timón · F.A.R.O.</title><style>
@page{size:letter;margin:16mm 15mm;}
*{margin:0;padding:0;box-sizing:border-box;}
body{font-family:Georgia,'Times New Roman',serif;font-size:11.5pt;line-height:1.55;color:#111;background:#fff;}
h1{font-family:Arial,Helvetica,sans-serif;font-size:15pt;color:#1e1b4b;margin-bottom:2mm;line-height:1.2;}
.tipo{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;color:#555;margin-bottom:3mm;}
.ruta{font-family:Arial,Helvetica,sans-serif;font-size:9pt;color:#4338ca;border-bottom:1.5pt solid #4338ca;padding-bottom:1.5mm;margin-bottom:3mm;display:flex;justify-content:space-between;gap:6mm;}
.etiqueta{border:1.2pt solid #4338ca;background:#eef2ff;border-radius:2mm;padding:2.5mm 3mm;font-family:Arial,Helvetica,sans-serif;font-size:9pt;line-height:1.4;margin-bottom:4mm;}
.idline{font-family:Arial,Helvetica,sans-serif;font-size:9pt;display:flex;gap:4mm;margin-bottom:3mm;}
.idline span.r{flex:1;border-bottom:0.8pt solid #666;}
p.t{text-align:justify;margin-bottom:2.6mm;text-indent:6mm;}
p.t:first-of-type{text-indent:0;}
h2{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#1e1b4b;margin:4mm 0 2mm;}
.sec{font-family:Arial,Helvetica,sans-serif;font-size:10.5pt;font-weight:700;color:#4338ca;background:#eef2ff;border-left:3pt solid #4338ca;padding:1.2mm 2.5mm;margin:4mm 0 2mm;}
.q{font-family:Arial,Helvetica,sans-serif;font-size:10pt;margin:2mm 0 1mm;}
.q .n{font-weight:700;color:#4338ca;}
.op{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;margin-left:7mm;}
.ln{border-bottom:0.8pt solid #888;height:6.5mm;}
.ln-alta{border-bottom:0.8pt solid #888;height:9mm;}
.fuente{font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;font-style:italic;}
.pauta{page-break-before:always;}
.pl{font-family:Arial,Helvetica,sans-serif;font-size:9pt;margin-bottom:1.6mm;text-align:justify;}
.pie{border-top:0.8pt solid #999;margin-top:5mm;padding-top:2mm;font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;display:flex;justify-content:space-between;gap:6mm;}
</style></head><body>${cuerpo}<div class="pie"><span>🏠 Proyecto Educativo F.A.R.O. · Estudio Mayor</span><span>🪞 El vigía y el timón${pieExtra||''}</span></div></body></html>`;
}
function _abreImpresion(doc){
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}
function imprimirLectura(clave){
  const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
  if(!meta||!card){showToast('⚠️ No se encontró la lectura');return;}
  sfx('click');
  const nota=card.querySelector('.lect-nota');
  const parrafos=[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  const cuerpo=`<div class="ruta"><span>🪞 Ruta de la Máquina que se Mira · Etapa 1 de 6</span><span>Lecturas 📖</span></div>`
    +`<h1>${meta.titulo}</h1><div class="tipo">${meta.tipo}</div>`
    +_etiquetaImpresa(meta)
    +`<div class="idline"><span>Lee:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
    +parrafos;
  _abreImpresion(_hojaImpresa(meta.titulo,cuerpo,' · '+meta.titulo));
}
function imprimirTodasLasLecturas(){
  sfx('click');
  let cuerpo=`<div class="ruta"><span>🪞 Ruta de la Máquina que se Mira · Etapa 1 de 6</span><span>Las cinco lecturas 📖</span></div>`
    +`<h1>Las cinco lecturas de «El vigía y el timón»</h1><div class="tipo">Un cuento, un capítulo, un ensayo y dos entrevistas imaginadas, sobre el mismo vigía</div>`
    +`<div class="etiqueta"><strong>⚠️ Ejercicios de estilo de la casa, en homenaje.</strong> Los cinco textos <strong>NO son obra de Jorge Luis Borges, de Miguel de Cervantes Saavedra ni de Yuval Noah Harari</strong>, y las dos entrevistas son <strong>imaginadas: los encuentros nunca ocurrieron</strong>. Las conversaciones con John H. Flavell, y entre Jesús Quintero y Antonio Gala, son invención del Proyecto Educativo F.A.R.O., que se declara como pastiche. Las personas son reales y <strong>toda obra, fecha y cifra citada dentro de los textos es real y comprobable</strong>; el único artificio permitido es la voz.</div>`;
  ['borges','cervantes','harari','entrevista','gala'].forEach((clave,i)=>{
    const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
    if(!card)return;
    const nota=card.querySelector('.lect-nota');
    cuerpo+=(i?'<div style="page-break-before:always;"></div>':'')
      +`<h2>${i+1}. ${meta.titulo}</h2><div class="tipo">${meta.tipo}</div>`
      +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
      +[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  });
  _abreImpresion(_hojaImpresa('Las cinco lecturas',cuerpo,' · Las cinco lecturas'));
}
function imprimirPreguntasLecturas(){
  sfx('click');
  const lineas=(n,alta)=>Array(n).fill('<div class="'+(alta?'ln-alta':'ln')+'"></div>').join('');
  let cuerpo=`<div class="ruta"><span>🪞 Ruta de la Máquina que se Mira · Etapa 1 de 6</span><span>Preguntas de las lecturas 📖</span></div>`
    +`<h1>Preguntas de las cinco lecturas</h1><div class="tipo">El vigía y el timón · 25 de comprensión lectora, 10 de completar y 10 de análisis complejo</div>`
    +`<div class="idline"><span>Nombre:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +`<div class="etiqueta">Se responde <strong>con los cinco textos delante</strong>: no es un examen de memoria. Las respuestas de las tres secciones van en la <strong>pauta de la última hoja</strong>, así que se resuelve antes de darle la vuelta. Los cinco textos son <strong>ejercicios de estilo de la casa</strong>: no son obra de Borges, Cervantes ni Harari, y las dos entrevistas son imaginadas (los encuentros nunca ocurrieron).</div>`;
  cuerpo+='<div class="sec">I. Comprensión lectora (25 preguntas)</div>';
  lectComprensionBank.forEach((q,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${q.q} <span class="fuente">(${q.t})</span></div>`;
    q.o.forEach(o=>{cuerpo+=`<div class="op">${o}</div>`;});
  });
  cuerpo+='<div class="sec">II. Completa la oración (10 preguntas)</div>';
  lectCompletarBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q.replace('___','_______________')} <span class="fuente">(${d.t})</span></div>`;
  });
  cuerpo+='<div class="sec">III. Análisis complejo (10 preguntas)</div>';
  lectAnalisisBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q}</div>`+lineas(3,true);
  });
  cuerpo+='<div class="pauta"><div class="sec">✅ Pauta completa de respuestas</div>';
  cuerpo+='<div class="pl"><strong>I. Comprensión lectora:</strong> '+lectComprensionBank.map((q,i)=>(i+1)+') '+'abcd'[q.c]).join(' · ')+'</div>';
  cuerpo+='<div class="pl"><strong>II. Completar:</strong> '+lectCompletarBank.map((d,i)=>(i+1)+') '+d.a).join(' · ')+'</div>';
  cuerpo+='<div class="pl" style="margin-top:2mm;"><strong>III. Análisis complejo (guías de corrección):</strong></div>';
  lectAnalisisBank.forEach((d,i)=>{cuerpo+=`<div class="pl"><strong>${i+1}.</strong> ${d.guia}</div>`;});
  cuerpo+='</div>';
  _abreImpresion(_hojaImpresa('Preguntas de las lecturas',cuerpo,' · Preguntas de las lecturas'));
}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue mirando tu estudio!','¡Muy buen trabajo!','¡Vigía en entrenamiento!','¡Ya separas el parte de la decisión!','¡Auditor del propio estudio!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🪞 ¡'+name+' completó la Etapa 1 de la Ruta de la Máquina que se Mira (El vigía y el timón)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

